/**
 * Badger Sprawl Runner - Main Entry Point
 * Initializes game loop, loads manifests, starts the engine
 */

import { GameLoop } from './engine/GameLoop';
import { SceneManager } from './engine/SceneManager';
import { EventBus } from './engine/EventBus';
import { Renderer } from './renderer/Renderer';
import { StageRunScene } from './scenes/StageRunScene';
import { DebugFlags } from './engine/DebugFlags';

async function main() {
  const canvas = document.querySelector('#game') as HTMLCanvasElement;
  if (!canvas) throw new Error('Canvas not found');

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D context not available');

  const W = canvas.width;
  const H = canvas.height;

  // Setup event bus
  const eventBus = new EventBus();

  // Setup scene manager
  const sceneContext = {
    eventBus,
    canvas,
  };
  const sceneManager = new SceneManager(sceneContext);

  // Setup renderer
  const renderer = new Renderer(ctx, W, H);

  // Create and push main scene
  const stageScene = new StageRunScene();
  sceneManager.push(stageScene);

  // Setup game loop
  const gameLoop = new GameLoop(
    canvas,
    (dt) => sceneManager.update(dt),
    (alpha) => {
      renderer.clear();
      renderer.drawBackground();
      sceneManager.render(renderer, alpha);
    }
  );

  // Debug toggle
  window.addEventListener('keydown', (e) => {
    if (e.code === 'KeyH') {
      DebugFlags.showHitboxes = !DebugFlags.showHitboxes;
    }
  });

  // Start the game
  gameLoop.start();
}

main().catch(console.error);
